UPDATE theme SET layout = jsonb_set(layout, '{tiles,latestDrop}',
  layout->'tiles'->'latestDrop' || '{"col": 1, "row": 1}'::jsonb) WHERE key = 'wave-03';
UPDATE theme SET layout = jsonb_set(layout, '{tiles,marquee}',
  layout->'tiles'->'marquee' || '{"col": 13, "row": 1}'::jsonb) WHERE key = 'wave-03';
UPDATE theme SET layout = jsonb_set(layout, '{tiles,projects}',
  layout->'tiles'->'projects' || '{"col": 13, "row": 9}'::jsonb) WHERE key = 'wave-03';
UPDATE theme SET layout = jsonb_set(layout, '{tiles,photoDrops}',
  layout->'tiles'->'photoDrops' || '{"col": 21}'::jsonb) WHERE key = 'wave-03';
UPDATE theme SET layout = jsonb_set(layout, '{tiles,today}',
  '{"col": 1, "row": 18, "colSpan": 19, "rowSpan": 11, "hidden": false}'::jsonb) WHERE key = 'wave-03';
UPDATE theme SET layout = jsonb_set(layout, '{mobileOrder}',
  '["today", "waveSwitcher", "music", "stats", "latestDrop", "photoDrops", "ride", "projects", "social", "calendar", "marquee"]'::jsonb)
  WHERE key = 'wave-03';

